#pragma once
// Unicode support for the tokenizer: the character classes of Qwen3.5's pre-tokenizer pattern, NFC normalization (the
// checkpoint's normalizer) and UTF-8 handling. Data is generated by tools/gen_unicode_tables.py (Unicode 15.0).
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

namespace dara::tokenizer {

bool is_letter(uint32_t cp);  // \p{L}
bool is_mark(uint32_t cp);    // \p{M}
bool is_number(uint32_t cp);  // \p{N}
bool is_space(uint32_t cp);   // \s = White_Space (U+0009-000D, 0020, 0085, 00A0, 1680, 2000-200A, 2028, 2029, 202F, 205F, 3000)

// NFC of a codepoint sequence (canonical decomposition, canonical ordering, canonical composition; Hangul algorithmic).
std::vector<uint32_t> nfc(const std::vector<uint32_t>& cps);

// ---- UTF-8 ---------------------------------------------------------------------------------------------
enum class Utf8Status { Ok, Invalid, Truncated };
// Decodes one codepoint at p[0..n). Returns bytes consumed (>= 1). On Invalid, `cp` is U+FFFD and the consumed length is
// the "maximal subpart" of an ill-formed sequence (so one replacement character per maximal subpart, as Rust's
// from_utf8_lossy and Python's errors="replace" produce). On Truncated the bytes are a valid prefix of a longer sequence
// that the input ended in the middle of; consumed is n and cp is unspecified.
size_t utf8_next(const uint8_t* p, size_t n, uint32_t& cp, Utf8Status& status);
std::vector<uint32_t> utf8_to_codepoints(const std::string& s);  // lossy: ill-formed input becomes U+FFFD
void utf8_append(std::string& out, uint32_t cp);
std::string codepoints_to_utf8(const std::vector<uint32_t>& cps);

}  // namespace dara::tokenizer
